INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 1, 'Organic Chemistry', 'Benzene Structure & Bonding (Diagram)', 'Easy', 'The Kekulé structure of benzene (C_6H_6) is shown. Counting every bond in the molecule (the delocalised π system counted as 3 π bonds), how many σ and π bonds does one benzene molecule contain?', 1, '<svg viewBox="-150 -85 300 170" xmlns="http://www.w3.org/2000/svg">
<rect x="-150" y="-85" width="300" height="170" fill="#f8fafc" rx="12"/>
<line x1="0" y1="-44" x2="38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="4.2" y1="-35.2" x2="28.4" y2="-21.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="-22" x2="38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="22" x2="0" y2="44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="28.4" y1="21.2" x2="4.2" y2="35.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="0" y1="44" x2="-38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="22" x2="-38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-32.6" y1="14" x2="-32.6" y2="-14" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="-22" x2="0" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
</svg>', 'σ bonds: 6 C–C (ring) + 6 C–H = 12. Each ring carbon is sp² hybridised and keeps one unhybridised p orbital; these six p orbitals overlap sideways to give the delocalised π cloud, equivalent to 3 π bonds in the Kekulé picture. Total: 12 σ and 3 π.', 'D');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '9 σ and 6 π');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '15 σ and 3 π');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '12 σ and 6 π');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '12 σ and 3 π');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 2, 'Organic Chemistry', 'Directive Influence in Aromatic Substitution (Diagram)', 'Medium', 'The compound shown (toluene) is mono-nitrated with conc. HNO_3 / conc. H_2SO_4. Which product(s) form mainly?', 1, '<svg viewBox="-150 -129.9 300 203.9" xmlns="http://www.w3.org/2000/svg">
<rect x="-150" y="-129.9" width="300" height="203.9" fill="#f8fafc" rx="12"/>
<line x1="0" y1="-44" x2="38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="4.2" y1="-35.2" x2="28.4" y2="-21.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="-22" x2="38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="22" x2="0" y2="44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="28.4" y1="21.2" x2="4.2" y2="35.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="0" y1="44" x2="-38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="22" x2="-38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-32.6" y1="14" x2="-32.6" y2="-14" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="-22" x2="0" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="0" y1="-44" x2="0" y2="-78" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<text x="-5.8" y="-88" dominant-baseline="central" text-anchor="start" font-family="Arial, sans-serif" font-size="17" font-weight="600" fill="#0f172a" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">CH<tspan dy="4" font-size="12">3</tspan><tspan dy="-4">​</tspan></text>
</svg>', 'The –CH_3 group is electron-donating (+I and hyperconjugation), so it activates the ring and directs the incoming NO_2^+ to the ortho and para positions, where the arenium ion has a resonance form with the positive charge on the carbon bearing CH_3 (a stable tertiary-like cation). Both o- and p-isomers form, with p usually major for steric reasons.', 'B');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'm-Nitrotoluene only');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'o-Nitrotoluene and p-nitrotoluene');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'p-Nitrotoluene exclusively');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'o-Nitrotoluene exclusively');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 3, 'Organic Chemistry', 'Meta Directing Groups (Diagram)', 'Medium', 'Nitrobenzene (shown) is heated with fuming HNO_3 / conc. H_2SO_4. What is the main product?', 1, '<svg viewBox="-151.8 -151.9 300 225.9" xmlns="http://www.w3.org/2000/svg">
<rect x="-151.8" y="-151.9" width="300" height="225.9" fill="#f8fafc" rx="12"/>
<line x1="0" y1="-44" x2="38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="4.2" y1="-35.2" x2="28.4" y2="-21.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="-22" x2="38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
