INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 5, 'Organic Chemistry', 'IUPAC Nomenclature of Alkanes (Chain Diagram)', 'Medium', 'In this skeletal (line-angle) formula each vertex and each end of a line is a carbon atom, with hydrogens implied. What is the IUPAC name of the compound?', 1, '<svg viewBox="-54.8 -52 300 170" xmlns="http://www.w3.org/2000/svg">
<rect x="-54.8" y="-52" width="300" height="170" fill="#f8fafc" rx="12"/>
<line x1="0" y1="22" x2="38.1" y2="0" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="0" x2="76.2" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="76.2" y1="22" x2="114.3" y2="0" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="114.3" y1="0" x2="152.4" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="152.4" y1="22" x2="190.5" y2="0" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="76.2" y1="22" x2="76.2" y2="66" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
</svg>', 'The longest continuous chain has 6 carbons (hexane). The one-carbon branch sits on the third carbon counted from the left end (and the fourth from the right), so we number from the end that gives the lower locant: 3. Name: 3-methylhexane. "4-Methylhexane" is never correct because it violates the lowest-locant rule, and the chain through the branch is shorter, so it is not 3-ethylpentane.', 'C');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '2-Methylhexane');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '4-Methylhexane');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '3-Methylhexane');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '3-Ethylpentane');
