<text x="108.5" y="110" dominant-baseline="central" text-anchor="start" font-family="Arial, sans-serif" font-size="17" font-weight="600" fill="#0f172a" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">CH<tspan dy="4" font-size="12">3</tspan><tspan dy="-4">​</tspan></text>
</svg>', 'The group –COOH (C=O with –OH on the same carbon) is a carboxylic acid. The group –O–C(=O)–CH_3 attached to the ring through oxygen is an ester (specifically an acetate ester); the free phenolic –OH of salicylic acid has been acetylated, so there is no phenol or ether.', 'D');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Carboxylic acid and ether');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Ester and ketone');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Phenol and carboxylic acid');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Carboxylic acid and ester');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 8, 'Organic Chemistry', 'Structural Isomerism (Chain Diagram)', 'Easy', 'Compounds I and II shown here both have the molecular formula C_4H_10. What type of isomerism do they exhibit?', 1, '<svg viewBox="-260 -74 388.1 194.6" xmlns="http://www.w3.org/2000/svg">
<rect x="-260" y="-74" width="388.1" height="194.6" fill="#f8fafc" rx="12"/>
<line x1="-230" y1="22" x2="-191.9" y2="0" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-191.9" y1="0" x2="-153.8" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-153.8" y1="22" x2="-115.7" y2="0" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="60" y1="0" x2="60" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="60" y1="0" x2="98.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="60" y1="0" x2="21.9" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<text x="-173" y="78" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">I</text>
<text x="60" y="78" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">II</text>
</svg>', 'I is butane (a straight four-carbon chain) and II is 2-methylpropane (isobutane, a branched chain). They share a formula and functional group but differ in the arrangement of the carbon skeleton, which is chain (skeletal) isomerism.', 'D');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'Position isomerism');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'Functional group isomerism');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Geometrical isomerism');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Chain isomerism');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 9, 'Organic Chemistry', 'Geometrical (cis-trans) Isomerism (Diagram)', 'Medium', 'P and Q are the two stereoisomers of but-2-ene (CH_3–CH=CH–CH_3), shown as skeletal formulas. Which statement is correct?', 1, '<svg viewBox="-222 -72.8 398 170" xmlns="http://www.w3.org/2000/svg">
<rect x="-222" y="-72.8" width="398" height="170" fill="#f8fafc" rx="12"/>
<line x1="-170" y1="-2.8" x2="-126" y2="-2.8" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-170" y1="2.8" x2="-126" y2="2.8" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-170" y1="0" x2="-192" y2="-38.1" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-126" y1="0" x2="-104" y2="-38.1" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="80" y1="-2.8" x2="124" y2="-2.8" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="80" y1="2.8" x2="124" y2="2.8" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="80" y1="0" x2="58" y2="-38.1" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="124" y1="0" x2="146" y2="38.1" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<text x="-148" y="50" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">P</text>
<text x="102" y="50" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">Q</text>
</svg>', 'On each double-bond carbon the substituent of higher priority is CH_3 (it outranks H). In P both CH_3 groups point to the same side of the C=C, so it is Z (cis). In Q they point to opposite sides, so it is E (trans). They have the same connectivity, so they are geometrical (cis-trans) stereoisomers.', 'B');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'P is the E (trans) isomer and Q is the Z (cis) isomer');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'P is the Z (cis) isomer and Q is the E (trans) isomer');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'Both P and Q are Z isomers');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'P and Q are structural isomers, not stereoisomers');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 10, 'Organic Chemistry', 'Aromaticity & Hückel Rule (Fused Ring Diagram)', 'Hard', 'Naphthalene (C_10H_8) is shown with its fused benzene rings. Which statement about its π electrons and aromaticity is correct?', 1, '<svg viewBox="-111.9 -85 300 170" xmlns="http://www.w3.org/2000/svg">
<rect x="-111.9" y="-85" width="300" height="170" fill="#f8fafc" rx="12"/>
<line x1="0" y1="-44" x2="38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="4.2" y1="-35.2" x2="28.4" y2="-21.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="-22" x2="38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="22" x2="0" y2="44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="28.4" y1="21.2" x2="4.2" y2="35.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="0" y1="44" x2="-38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="22" x2="-38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-32.6" y1="14" x2="-32.6" y2="-14" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="-22" x2="0" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="76.2" y1="-44" x2="114.3" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="80.4" y1="-35.2" x2="104.6" y2="-21.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="114.3" y1="-22" x2="114.3" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="114.3" y1="22" x2="76.2" y2="44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="104.6" y1="21.2" x2="80.4" y2="35.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="76.2" y1="44" x2="38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="-22" x2="76.2" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
</svg>', 'Naphthalene has 10 sp² carbons, each contributing one p electron to a planar, fully conjugated cyclic system: 5 double bonds × 2 = 10 π electrons. Hückel’s rule 4n + 2 is satisfied for n = 2, so the molecule is aromatic.', 'C');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '8 π electrons; anti-aromatic');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '10 π electrons; non-aromatic');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '10 π electrons; aromatic (4n + 2 with n = 2)');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '12 π electrons; aromatic (4n + 2 with n = 3)');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 11, 'Organic Chemistry', 'Acidity of Phenol vs Alcohol (Diagram)', 'Hard', 'Compound A (phenol) and compound B (ethanol) are shown. Which one is the stronger acid, and why?', 1, '<svg viewBox="-178.1 -129.9 375.4 248.5" xmlns="http://www.w3.org/2000/svg">
<rect x="-178.1" y="-129.9" width="375.4" height="248.5" fill="#f8fafc" rx="12"/>
<line x1="-110" y1="-44" x2="-71.9" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-105.8" y1="-35.2" x2="-81.6" y2="-21.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-71.9" y1="-22" x2="-71.9" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-71.9" y1="22" x2="-110" y2="44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-81.6" y1="21.2" x2="-105.8" y2="35.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-110" y1="44" x2="-148.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-148.1" y1="22" x2="-148.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-142.6" y1="14" x2="-142.6" y2="-14" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-148.1" y1="-22" x2="-110" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-110" y1="-44" x2="-110" y2="-77" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<text x="-115.8" y="-88" dominant-baseline="central" text-anchor="start" font-family="Arial, sans-serif" font-size="17" font-weight="600" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">OH</text>
<line x1="70" y1="22" x2="108.1" y2="0" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="108.1" y1="0" x2="136.7" y2="16.5" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<text x="140.4" y="22" dominant-baseline="central" text-anchor="start" font-family="Arial, sans-serif" font-size="17" font-weight="600" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">OH</text>
<text x="-110" y="76" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">A</text>
<text x="108" y="76" dominant-baseline="central" text-anchor="middle" font-family="Arial, sans-serif" font-size="18" font-weight="700" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">B</text>
</svg>', 'On losing H^+, phenol gives the phenoxide ion, whose negative charge is delocalised over the ring (ortho and para carbons) by resonance, which stabilises the conjugate base. In ethoxide the charge stays on oxygen and is destabilised by the +I effect of the ethyl group. Hence phenol (pK_a ≈ 10) is far more acidic than ethanol (pK_a ≈ 16).', 'A');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', 'A, because the phenoxide ion is stabilised by resonance with the benzene ring');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', 'B, because the ethyl group donates electrons and stabilises the ethoxide ion');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', 'A, because the O–H bond in phenol is longer than the O–H bond in ethanol');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', 'Both are equally acidic because both contain an –OH group');
INSERT INTO questions (exam_id, position, section, topic, difficulty, question_text, has_diagram, svg_diagram, explanation, correct_option) VALUES (@org_exam, 12, 'Organic Chemistry', 'Degree of Unsaturation (Diagram)', 'Hard', 'For the compound shown (C_9H_8O), what is the degree of unsaturation (double-bond equivalents, DBE), and how is it made up?', 1, '<svg viewBox="-87.6 -129.9 300 203.9" xmlns="http://www.w3.org/2000/svg">
<rect x="-87.6" y="-129.9" width="300" height="203.9" fill="#f8fafc" rx="12"/>
<line x1="0" y1="-44" x2="38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="4.2" y1="-35.2" x2="28.4" y2="-21.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="-22" x2="38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="22" x2="0" y2="44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="28.4" y1="21.2" x2="4.2" y2="35.2" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="0" y1="44" x2="-38.1" y2="22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="22" x2="-38.1" y2="-22" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-32.6" y1="14" x2="-32.6" y2="-14" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="-38.1" y1="-22" x2="0" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="38.1" y1="-22" x2="76.2" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="77.6" y1="-46.4" x2="115.7" y2="-24.4" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="74.8" y1="-41.6" x2="112.9" y2="-19.6" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="114.3" y1="-22" x2="152.4" y2="-44" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="149.6" y1="-44" x2="149.6" y2="-78" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<line x1="155.2" y1="-44" x2="155.2" y2="-78" stroke="#0f172a" stroke-width="2.4" stroke-linecap="round"/>
<text x="146.6" y="-88" dominant-baseline="central" text-anchor="start" font-family="Arial, sans-serif" font-size="17" font-weight="600" fill="#b91c1c" stroke="#f8fafc" stroke-width="4" paint-order="stroke" stroke-linejoin="round">O</text>
</svg>', 'DBE = (2C + 2 − H)/2 = (2×9 + 2 − 8)/2 = 6. Counting from the structure: 1 ring (the benzene ring itself) + 3 C=C in the Kekulé ring + 1 side-chain C=C + 1 C=O = 6, which matches the formula.', 'B');
SET @q = LAST_INSERT_ID();
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'A', '5 = 3 ring C=C + 1 C=C + 1 C=O');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'B', '6 = 1 ring + 3 ring C=C + 1 C=C + 1 C=O');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'C', '7 = 1 ring + 3 ring C=C + 2 C=C + 1 C=O');
INSERT INTO question_options (question_id, label, option_text) VALUES (@q, 'D', '4 = 3 ring C=C + 1 C=O');
